/**
 * Lỗi trả về cho ứng dụng. Thông điệp bằng tiếng Việt, hiển thị được cho người dùng.
 */
sealed class LvhvException(message: String): kotlin.Exception(message) {
        
    /**
     * Ngày dương không tồn tại (ví dụ 30/2).
     */
        class InvalidDate(message: String) : LvhvException(message)
        
    /**
     * Ngoài phạm vi 2000–3000.
     */
        class OutOfRange(message: String) : LvhvException(message)
        
    /**
     * Mã việc không có trong danh sách `activities_json()`.
     */
        class UnknownActivity(message: String) : LvhvException(message)
        
    /**
     * Khoảng ngày sai (kết thúc trước bắt đầu, hoặc dài quá một năm).
     */
        class BadRange(message: String) : LvhvException(message)
        
    /**
     * Chức năng chưa có trong bản dựng này.
     */
        class Unavailable(message: String) : LvhvException(message)
        

    companion object ErrorHandler : UniffiRustCallStatusErrorHandler<LvhvException> {
        override fun lift(error_buf: RustBuffer.ByValue): LvhvException = FfiConverterTypeLvhvError.lift(error_buf)
    }
}

/**
 * @suppress
 */
public object FfiConverterTypeLvhvError : FfiConverterRustBuffer<LvhvException> {
    override fun read(buf: ByteBuffer): LvhvException {
        
            return when(buf.getInt()) {
            1 -> LvhvException.InvalidDate(FfiConverterString.read(buf))
            2 -> LvhvException.OutOfRange(FfiConverterString.read(buf))
            3 -> LvhvException.UnknownActivity(FfiConverterString.read(buf))
            4 -> LvhvException.BadRange(FfiConverterString.read(buf))
            5 -> LvhvException.Unavailable(FfiConverterString.read(buf))
            else -> throw RuntimeException("invalid error enum value, something is very wrong!!")
        }
        
    }

    override fun allocationSize(value: LvhvException): ULong {
        return 4UL
    }

    override fun write(value: LvhvException, buf: ByteBuffer) {
        when(value) {
            is LvhvException.InvalidDate -> {
                buf.putInt(1)
                Unit
            }
            is LvhvException.OutOfRange -> {
                buf.putInt(2)
                Unit
            }
            is LvhvException.UnknownActivity -> {
                buf.putInt(3)
                Unit
            }
            is LvhvException.BadRange -> {
                buf.putInt(4)
                Unit
            }
            is LvhvException.Unavailable -> {
                buf.putInt(5)
                Unit
            }
        }.let { /* this makes the `when` an expression, which ensures it is exhaustive */ }
    }

}




/**
 * @suppress
 */
public object FfiConverterOptionalInt: FfiConverterRustBuffer<kotlin.Int?> {
    override fun read(buf: ByteBuffer): kotlin.Int? {
        if (buf.get().toInt() == 0) {
            return null
        }
        return FfiConverterInt.read(buf)
    }

    override fun allocationSize(value: kotlin.Int?): ULong {
        if (value == null) {
            return 1UL
        } else {
            return 1UL + FfiConverterInt.allocationSize(value)
        }
    }

    override fun write(value: kotlin.Int?, buf: ByteBuffer) {
        if (value == null) {
            buf.put(0)
        } else {
            buf.put(1)
            FfiConverterInt.write(value, buf)
        }
    }
}




