}




/**
 * @suppress
 */
public object FfiConverterSequenceTypeLunarDay: FfiConverterRustBuffer<List<LunarDay>> {
    override fun read(buf: ByteBuffer): List<LunarDay> {
        val len = buf.getInt()
        return List<LunarDay>(len) {
            FfiConverterTypeLunarDay.read(buf)
        }
    }

    override fun allocationSize(value: List<LunarDay>): ULong {
        val sizeForLength = 4UL
        val sizeForItems = value.map { FfiConverterTypeLunarDay.allocationSize(it) }.sum()
        return sizeForLength + sizeForItems
    }

    override fun write(value: List<LunarDay>, buf: ByteBuffer) {
        buf.putInt(value.size)
        value.iterator().forEach {
            FfiConverterTypeLunarDay.write(it, buf)
        }
    }
}
